void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Notify.init();
  final store = RoshdStore();
  await store.load();
  runApp(RoshdApp(store: store));
}

String tr(String lang, String fa, String en) => lang == 'fa' ? fa : en;
String newId() => DateTime.now().microsecondsSinceEpoch.toString() + '_' + Random().nextInt(999999).toString();
bool sameDay(DateTime a, DateTime b) => a.year == b.year && a.month == b.month && a.day == b.day;
String dateLabel(DateTime d, String lang) {
  if (lang == 'en') return DateFormat('EEE, MMM d').format(d);
  final j = Jalali.fromDateTime(d);
  return j.year.toString() + '/' + j.month.toString().padLeft(2, '0') + '/' + j.day.toString().padLeft(2, '0');
}
String hm(DateTime d) => DateFormat('HH:mm').format(d);

class Task {
  String id,title,subject; DateTime at; int minutes,priority; bool done;
  Task({required this.id,required this.title,required this.subject,required this.at,required this.minutes,this.priority=2,this.done=false});
  Map<String,dynamic> toJson()=>{'id':id,'title':title,'subject':subject,'at':at.toIso8601String(),'minutes':minutes,'priority':priority,'done':done};
  factory Task.fromJson(Map<String,dynamic> j)=>Task(id:(j['id']??newId()).toString(),title:(j['title']??'').toString(),subject:(j['subject']??'عمومی').toString(),at:DateTime.tryParse((j['at']??'').toString())??DateTime.now(),minutes:(j['minutes'] as num?)?.toInt()??30,priority:(j['priority'] as num?)?.toInt()??2,done:j['done']==true);
}
class SessionLog {
  DateTime at; int minutes; String subject;
  SessionLog({required this.at,required this.minutes,required this.subject});
  Map<String,dynamic> toJson()=>{'at':at.toIso8601String(),'minutes':minutes,'subject':subject};
  factory SessionLog.fromJson(Map<String,dynamic> j)=>SessionLog(at:DateTime.tryParse((j['at']??'').toString())??DateTime.now(),minutes:(j['minutes'] as num?)?.toInt()??0,subject:(j['subject']??'عمومی').toString());
}
class Subject {
  String name; int goal; int color;
  Subject({required this.name,this.goal=180,this.color=0xff7bf6df});
  Map<String,dynamic> toJson()=>{'name':name,'goal':goal,'color':color};
  factory Subject.fromJson(Map<String,dynamic> j)=>Subject(name:(j['name']??'عمومی').toString(),goal:(j['goal'] as num?)?.toInt()??180,color:(j['color'] as num?)?.toInt()??0xff7bf6df);
}
class CardItem {
  String id,deck,front,back; int mastery;
  CardItem({required this.id,required this.deck,required this.front,required this.back,this.mastery=0});
  Map<String,dynamic> toJson()=>{'id':id,'deck':deck,'front':front,'back':back,'mastery':mastery};
  factory CardItem.fromJson(Map<String,dynamic> j)=>CardItem(id:(j['id']??newId()).toString(),deck:(j['deck']??'عمومی').toString(),front:(j['front']??'').toString(),back:(j['back']??'').toString(),mastery:(j['mastery'] as num?)?.toInt()??0);
}
class Exam {
  String id,title,subject; DateTime at;
  Exam({required this.id,required this.title,required this.subject,required this.at});
  Map<String,dynamic> toJson()=>{'id':id,'title':title,'subject':subject,'at':at.toIso8601String()};
  factory Exam.fromJson(Map<String,dynamic> j)=>Exam(id:(j['id']??newId()).toString(),title:(j['title']??'').toString(),subject:(j['subject']??'عمومی').toString(),at:DateTime.tryParse((j['at']??'').toString())??DateTime.now());
}
class NoteItem {
  String id,title,body,subject; DateTime at;
  NoteItem({required this.id,required this.title,required this.body,required this.subject,required this.at});
  Map<String,dynamic> toJson()=>{'id':id,'title':title,'body':body,'subject':subject,'at':at.toIso8601String()};
  factory NoteItem.fromJson(Map<String,dynamic> j)=>NoteItem(id:(j['id']??newId()).toString(),title:(j['title']??'').toString(),body:(j['body']??'').toString(),subject:(j['subject']??'عمومی').toString(),at:DateTime.tryParse((j['at']??'').toString())??DateTime.now());
}

class RoshdStore extends ChangeNotifier {
  final tasks=<Task>[], logs=<SessionLog>[], subjects=<Subject>[], cards=<CardItem>[], exams=<Exam>[], notes=<NoteItem>[];
  String lang='fa',accent='aurora',alarm='soft'; ThemeMode mode=ThemeMode.dark;
  int goal=180,tab=0; bool notifications=true,sounds=true; double volume=.55;
  late SharedPreferences p;
  Future<void> load() async {
    p=await SharedPreferences.getInstance();
    lang=p.getString('lang')??'fa'; accent=p.getString('accent')??'aurora'; alarm=p.getString('alarm')??'soft';
    mode=p.getBool('light')==true?ThemeMode.light:ThemeMode.dark; goal=p.getInt('goal')??180;
    notifications=p.getBool('notifications')??true; sounds=p.getBool('sounds')??true; volume=p.getDouble('volume')??.55;
    tasks..clear()..addAll(read('tasks',Task.fromJson)); logs..clear()..addAll(read('logs',SessionLog.fromJson));
    subjects..clear()..addAll(read('subjects',Subject.fromJson)); cards..clear()..addAll(read('cards',CardItem.fromJson));
    exams..clear()..addAll(read('exams',Exam.fromJson)); notes..clear()..addAll(read('notes',NoteItem.fromJson));
    if(subjects.isEmpty){subjects.addAll([Subject(name:'ریاضی',goal:240,color:0xff7bf6df),Subject(name:'علوم',goal:180,color:0xff8a7cff),Subject(name:'فارسی',goal:150,color:0xfff4d47c),Subject(name:'انگلیسی',goal:120,color:0xffff8fb1)]);await save();}
    notifyListeners();
  }
  List<T> read<T>(String key,T Function(Map<String,dynamic>) fn){
    final raw=p.getString(key); if(raw==null)return [];
    try{final v=jsonDecode(raw);if(v is! List)return [];return v.whereType<Map>().map((e)=>fn(Map<String,dynamic>.from(e))).toList();}catch(_){return [];}
  }
  Future<void> save() async {
    await Future.wait([
      p.setString('tasks',jsonEncode(tasks.map((x)=>x.toJson()).toList())),
      p.setString('logs',jsonEncode(logs.map((x)=>x.toJson()).toList())),
      p.setString('subjects',jsonEncode(subjects.map((x)=>x.toJson()).toList())),
      p.setString('cards',jsonEncode(cards.map((x)=>x.toJson()).toList())),
      p.setString('exams',jsonEncode(exams.map((x)=>x.toJson()).toList())),
      p.setString('notes',jsonEncode(notes.map((x)=>x.toJson()).toList())),
      p.setString('lang',lang),p.setString('accent',accent),p.setString('alarm',alarm),p.setBool('light',mode==ThemeMode.light),p.setInt('goal',goal),p.setBool('notifications',notifications),p.setBool('sounds',sounds),p.setDouble('volume',volume)
    ]);notifyListeners();
  }
  List<Task> today() => tasks.where((x)=>sameDay(x.at,DateTime.now())).toList()..sort((a,b)=>a.at.compareTo(b.at));
  int todayMinutes()=>logs.where((x)=>sameDay(x.at,DateTime.now())).fold(0,(a,x)=>a+x.minutes);
  int totalMinutes()=>logs.fold(0,(a,x)=>a+x.minutes);
  double dayProgress()=>goal<=0?0:min(1,todayMinutes()/goal);
  int subjectMinutes(String s)=>logs.where((x)=>x.subject==s).fold(0,(a,x)=>a+x.minutes);
  int streak(){var d=DateTime.now();final set=logs.map((x)=>DateTime(x.at.year,x.at.month,x.at.day)).toSet();var n=0;while(set.contains(DateTime(d.year,d.month,d.day))){n++;d=d.subtract(const Duration(days:1));}return n;}
  Future<void> addTask(Task x)async{tasks.add(x);await save();}
  Future<void> toggle(Task x)async{x.done=!x.done;await save();}
  Future<void> deleteTask(Task x)async{tasks.remove(x);await save();}
  Future<void> addLog(SessionLog x)async{logs.add(x);await save();}
  Future<void> addCard(CardItem x)async{cards.add(x);await save();}
  Future<void> rate(CardItem x,bool known)async{x.mastery=max(0,min(5,x.mastery+(known?1:-1)));await save();}
  Future<void> addExam(Exam x)async{exams.add(x);await save();}
  Future<void> addNote(NoteItem x)async{notes.add(x);await save();}
  String backup()=>const JsonEncoder.withIndent('  ').convert({'product':'Roshd','studio':'AdLand Studio','version':'1.0.0','settings':{'lang':lang,'goal':goal,'accent':accent,'alarm':alarm,'volume':volume,'light':mode==ThemeMode.light},'tasks':tasks.map((x)=>x.toJson()).toList(),'logs':logs.map((x)=>x.toJson()).toList(),'subjects':subjects.map((x)=>x.toJson()).toList(),'cards':cards.map((x)=>x.toJson()).toList(),'exams':exams.map((x)=>x.toJson()).toList(),'notes':notes.map((x)=>x.toJson()).toList()});
  Future<bool> restore(String raw)async{try{final m=jsonDecode(raw);if(m is! Map)return false;tasks..clear()..addAll((m['tasks'] as List???[]).whereType<Map>().map((x)=>Task.fromJson(Map<String,dynamic>.from(x))));logs..clear()..addAll((m['logs'] as List???[]).whereType<Map>().map((x)=>SessionLog.fromJson(Map<String,dynamic>.from(x))));subjects..clear()..addAll((m['subjects'] as List???[]).whereType<Map>().map((x)=>Subject.fromJson(Map<String,dynamic>.from(x))));cards..clear()..addAll((m['cards'] as List???[]).whereType<Map>().map((x)=>CardItem.fromJson(Map<String,dynamic>.from(x))));exams..clear()..addAll((m['exams'] as List???[]).whereType<Map>().map((x)=>Exam.fromJson(Map<String,dynamic>.from(x))));notes..clear()..addAll((m['notes'] as List???[]).whereType<Map>().map((x)=>NoteItem.fromJson(Map<String,dynamic>.from(x))));await save();return true;}catch(_){return false;}}
}

class Notify {
  static final p=FlutterLocalNotificationsPlugin();
  static Future<void> init() async {
    const a=AndroidInitializationSettings('ic_launcher');
    final d=DarwinInitializationSettings(requestAlertPermission:false,requestBadgePermission:false,requestSoundPermission:false);
    final w=WindowsInitializationSettings(appName:'Roshd',appUserModelId:'com.adland.roshd',guid:'7d6a41f6-6a3d-4a3c-8c87-cfe0d1b6e2af');
    await p.initialize(settings:InitializationSettings(android:a,iOS:d,macOS:d,windows:w));
  }
  static Future<void> permissions()async{
    await p.resolvePlatformSpecificImplementation<AndroidFlutterLocalNotificationsPlugin>()?.requestNotificationsPermission();
    await p.resolvePlatformSpecificImplementation<IOSFlutterLocalNotificationsPlugin>()?.requestPermissions(alert:true,sound:true,badge:true);
    await p.resolvePlatformSpecificImplementation<MacOSFlutterLocalNotificationsPlugin>()?.requestPermissions(alert:true,sound:true,badge:true);
  }
  static Future<void> show(String title,String body)async{
    const n=NotificationDetails(android:AndroidNotificationDetails('roshd_focus','Roshd Focus',channelDescription:'Study alerts',importance:Importance.high,priority:Priority.high),iOS:DarwinNotificationDetails(),macOS:DarwinNotificationDetails(),windows:WindowsNotificationDetails());
    await p.show(id:DateTime.now().millisecondsSinceEpoch.remainder(2147483647),title:title,body:body,notificationDetails:n);
  }
}

class SoundLab {
  final player=AudioPlayer();
  Future<void> stop()=>player.stop();
  Future<void> play(String kind,double vol)async{
    await player.setReleaseMode(ReleaseMode.loop);await player.setVolume(vol);await player.setSourceBytes(wave(kind),mimeType:'audio/wav');await player.resume();
  }
  Future<void> alarm(String kind,double vol)async{
    await player.setReleaseMode(ReleaseMode.stop);await player.setVolume(vol);await player.setSourceBytes(alarmWave(kind),mimeType:'audio/wav');await player.resume();
  }
  Uint8List wave(String kind){const rate=8000,seconds=8;final s=Int16List(rate*seconds);var seed=kind.codeUnits.fold(7,(a,b)=>(a*31+b)&0x7fffffff);double r(){seed=(1664525*seed+1013904223)&0x7fffffff;return seed/0x7fffffff*2-1;}var brown=0.0;
    for(var i=0;i<s.length;i++){final t=i/rate;var x=0.0;if(kind=='rain'){x=r()*.12;if(r()>.997)x+=r()*.4*exp(-((t*9)%1)*5);}else if(kind=='ocean'){final q=.5+.5*sin(t*.21);x=r()*(.04+.14*q);}else if(kind=='brown'){brown=brown*.985+r()*.02;x=brown*3.2;}else if(kind=='white'){x=r()*.15;}else if(kind=='focus'){x=sin(t*2*pi*174)*.04+sin(t*2*pi*261)*.025+sin(t*2*pi*392)*.012+r()*.003;}else if(kind=='fire'){x=sin(t*2*pi*70)*.026+r()*.025;if(r()>.998)x+=r()*.25;}else{x=sin(t*2*pi*110)*.022+sin(t*2*pi*164)*.012+r()*.014;}final f=min(1.0,min(t*3,(seconds-t)*3));s[i]=(x*f*9000).clamp(-32767,32767).toInt();}return wav(s,rate);}
  Uint8List alarmWave(String kind){const rate=12000,seconds=1.7;final s=Int16List((rate*seconds).round());for(var i=0;i<s.length;i++){final t=i/rate;double x;if(kind=='bell')x=sin(2*pi*880*t)*.38+sin(2*pi*1320*t)*.16;else if(kind=='digital')x=(sin(2*pi*980*t)+sin(2*pi*1460*t))*.18;else if(kind=='rise'){final f=520+500*min(1,t/seconds);x=sin(2*pi*f*t)*.28;}else x=sin(2*pi*523.25*t)*.28+sin(2*pi*659.25*t)*.12;final e=min(1.0,t*14)*pow(max(0,1-t/seconds),1.6);s[i]=(x*e*15000).clamp(-32767,32767).toInt();}return wav(s,rate);}
  Uint8List wav(Int16List s,int rate){final n=s.length*2;final b=ByteData(n+44);void a(int p,String x){for(var i=0;i<x.length;i++)b.setUint8(p+i,x.codeUnitAt(i));}a(0,'RIFF');b.setUint32(4,36+n,Endian.little);a(8,'WAVE');a(12,'fmt ');b.setUint32(16,16,Endian.little);b.setUint16(20,1,Endian.little);b.setUint16(22,1,Endian.little);b.setUint32(24,rate,Endian.little);b.setUint32(28,rate*2,Endian.little);b.setUint16(32,2,Endian.little);b.setUint16(34,16,Endian.little);a(36,'data');b.setUint32(40,n,Endian.little);for(var i=0;i<s.length;i++)b.setInt16(44+i*2,s[i],Endian.little);return b.buffer.asUint8List();}
  void dispose()=>player.dispose();
}

class RoshdApp extends StatelessWidget{
  final RoshdStore store;const RoshdApp({super.key,required this.store});
  @override Widget build(BuildContext context)=>AnimatedBuilder(animation:store,builder:(_,__){
    final seed=switch(store.accent){'violet'=>const Color(0xff8a7cff),'gold'=>const Color(0xffd9b55d),'mint'=>const Color(0xff7bf6df),_=>const Color(0xff6d8cff)};
    final scheme=ColorScheme.fromSeed(seedColor:seed,brightness:store.mode==ThemeMode.dark?Brightness.dark:Brightness.light);
    final fam=store.lang=='fa'?GoogleFonts.vazirmatn().fontFamily:GoogleFonts.manrope().fontFamily;
    return MaterialApp(debugShowCheckedModeBanner:false,title:'Roshd | رشد',theme:ThemeData(useMaterial3:true,colorScheme:scheme,fontFamily:fam,brightness:scheme.brightness,scaffoldBackgroundColor:store.mode==ThemeMode.dark?const Color(0xff060914):const Color(0xfff3f6fb),cardTheme:CardTheme(margin:EdgeInsets.zero,elevation:0,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(22)))),home:Directionality(textDirection:store.lang=='fa'?TextDirection.rtl:TextDirection.ltr,child:Shell(store:store)));
  });
}

