class _AuraState extends State<Aura>with SingleTickerProviderStateMixin{late final c=AnimationController(vsync:this,duration:const Duration(seconds:16))..repeat();@override void dispose(){c.dispose();super.dispose();}@override Widget build(BuildContext context)=>AnimatedBuilder(animation:c,builder:(_,__)=>CustomPaint(painter:AuraPainter(c.value),child:const SizedBox.expand()));}
class AuraPainter extends CustomPainter{final double t;AuraPainter(this.t);@override void paint(Canvas canvas,Size s){final p=Paint();final pts=[Offset(s.width*(.12+.04*sin(t*2*pi)),s.height*.1),Offset(s.width*.9,s.height*(.35+.05*cos(t*2*pi))),Offset(s.width*.5,s.height*.92)];final cs=[const Color(0xff6d8cff),const Color(0xffd9b55d),const Color(0xff7bf6df)];for(var i=0;i<3;i++){p.shader=RadialGradient(colors:[cs[i].withOpacity(.08),Colors.transparent]).createShader(Rect.fromCircle(center:pts[i],radius:s.shortestSide*.4));canvas.drawCircle(pts[i],s.shortestSide*.4,p);}}@override bool shouldRepaint(covariant AuraPainter old)=>true;}

