class Insights extends StatelessWidget{final RoshdStore store;const Insights({super.key,required this.store});@override Widget build(BuildContext c){final fa=store.lang=='fa';final w=List.generate(7,(i){final d=DateTime.now().subtract(Duration(days:6-i));return store.logs.where((x)=>sameDay(x.at,d)).fold(0,(a,x)=>a+x.minutes);});final maxY=max(60,w.reduce(max)+40).toDouble();return ListView(children:[Text(fa?'تحلیل پیشرفت':'Insights',style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w900)),const SizedBox(height:10),GridView.count(crossAxisCount:MediaQuery.sizeOf(c).width>900?3:1,shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),children:[Metric(icon:Icons.timer,value:store.totalMinutes().toString(),text:fa?'کل مطالعه':'Total study'),Metric(icon:Icons.auto_graph,value:w.fold(0,(a,b)=>a+b).toString(),text:fa?'۷ روز اخیر':'Last 7 days'),Metric(icon:Icons.local_fire_department,value:store.streak().toString(),text:fa?'زنجیره':'Streak')]),const SizedBox(height:10),Glass(child:SizedBox(height:300,child:BarChart(BarChartData(maxY:maxY,borderData:FlBorderData(show:false),gridData:const FlGridData(show:false),titlesData:FlTitlesData(topTitles:const AxisTitles(sideTitles:SideTitles(showTitles:false)),rightTitles:const AxisTitles(sideTitles:SideTitles(showTitles:false)),leftTitles:AxisTitles(sideTitles:SideTitles(showTitles:true,reservedSize:34)),bottomTitles:AxisTitles(sideTitles:SideTitles(showTitles:true,getTitlesWidget:(v,m)=>Padding(padding:const EdgeInsets.only(top:7),child:Text(DateFormat('E').format(DateTime.now().subtract(Duration(days:6-v.toInt()))))))),barGroups:List.generate(7,(i)=>BarChartGroupData(x:i,barRods:[BarChartRodData(toY:w[i].toDouble(),width:22,borderRadius:BorderRadius.circular(7),color:Theme.of(c).colorScheme.primary)]))))),const SizedBox(height:10),Glass(child:Text(fa?'پیشرفت پایدار از یک برنامهٔ واقعی می‌آید. ساعت مطالعهٔ ثابت، مرور کوتاه و استراحت منظم را جدی بگیر.':'Sustainable progress comes from a realistic routine: fixed study times, short review and regular breaks.',style:Theme.of(c).textTheme.bodyMedium?.copyWith(height:1.8,color:Theme.of(c).colorScheme.onSurfaceVariant)))]);}}
class More extends StatelessWidget{final RoshdStore store;final SoundLab audio;const More({super.key,required this.store,required this.audio});
  Future<void> copy(BuildContext c)async{await Clipboard.setData(ClipboardData(text:store.backup()));if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text(store.lang=='fa'?'پشتیبان در کلیپ‌بورد کپی شد.':'Backup copied to clipboard.')));}
  Future<void> restore(BuildContext c)async{final d=await Clipboard.getData(Clipboard.kTextPlain);final ok=await store.restore(d?.text??'');if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text(ok?(store.lang=='fa'?'بازیابی شد.':'Restore complete.'):(store.lang=='fa'?'پشتیبان معتبر پیدا نشد.':'No valid backup found.'))));}
  @override Widget build(BuildContext c){final fa=store.lang=='fa';return ListView(children:[Text(fa?'بیشتر و تنظیمات':'More & settings',style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w900)),const SizedBox(height:10),Glass(child:Column(children:[
    ListTile(leading:const Icon(Icons.translate),title:Text(fa?'زبان':'Language'),subtitle:Text(fa?'فارسی · English':'English · فارسی'),trailing:Switch(value:store.lang=='en',onChanged:(v)=>store.setLang(v?'en':'fa'))),
    ListTile(leading:const Icon(Icons.dark_mode),title:Text(fa?'ظاهر':'Appearance'),trailing:Switch(value:store.mode==ThemeMode.dark,onChanged:(v){store.mode=v?ThemeMode.dark:ThemeMode.light;store.save();})),
    ListTile(leading:const Icon(Icons.notifications_active),title:Text(fa?'اعلان‌ها':'Notifications'),trailing:Switch(value:store.notifications,onChanged:(v){store.notifications=v;store.save();if(v)Notify.permissions();})),
    ListTile(leading:const Icon(Icons.volume_up),title:Text(fa?'صداهای مطالعه':'Study sounds'),trailing:Switch(value:store.sounds,onChanged:(v){store.sounds=v;store.save();if(!v)audio.stop();}))
  ])),const SizedBox(height:10),Glass(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Head(fa:'هدف روزانه',en:'Daily goal'),const SizedBox(height:8),Wrap(spacing:7,children:[60,90,120,180,240,300].map((m)=>ChoiceChip(selected:store.goal==m,label:Text(m.toString()),onSelected:(_){store.goal=m;store.save();})).toList())])),const SizedBox(height:10),Glass(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Head(fa:'پشتیبان‌گیری',en:'Backup'),Text(fa?'برای جابه‌جایی دستگاه‌ها JSON را کپی کن.':'Copy JSON backup to move between devices.'),const SizedBox(height:8),Wrap(spacing:8,children:[FilledButton.icon(onPressed:()=>copy(c),icon:const Icon(Icons.copy_all),label:Text(fa?'کپی پشتیبان':'Copy backup')),OutlinedButton.icon(onPressed:()=>restore(c),icon:const Icon(Icons.restore),label:Text(fa?'بازیابی':'Restore'))])])),const SizedBox(height:10),Glass(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Chip(avatar:Icon(Icons.auto_awesome,size:15),label:Text('AdLand Studio')),const SizedBox(height:8),Text(fa?'Roshd محصول AdLand Studio است؛ فارسی در مرکز تجربه قرار دارد و English گزینهٔ دوم است.':'Roshd is a product of AdLand Studio, with Persian first and English second.',style:Theme.of(c).textTheme.bodyMedium?.copyWith(height:1.8,color:Theme.of(c).colorScheme.onSurfaceVariant))]))]);}
